pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // Bound v to avoid overflow or unrealistic values (not required by contract but typical)
        v = bound(v, 0, 1000);
        // Only test when _tos array is empty
        vm.assume(_tos.length == 0);
        // Call transfer - if it does not revert, it must return true
        bool success;
        bool returnValue;
        try c.transfer(from, caddress, _tos, v) returns (bool val) {
            success = true;
            returnValue = val;
        } catch {
            success = false;
        }
        // The reference C should NOT revert and should return true
        assertTrue(success && returnValue);
    }
}

